CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY, first_seen TEXT NOT NULL,last_seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS boots(device TEXT NOT NULL,boot TEXT NOT NULL,day TEXT NOT NULL,reset_reason TEXT NOT NULL DEFAULT 'not_reported',PRIMARY KEY(device,boot));
CREATE TABLE IF NOT EXISTS aggregates(receipt TEXT PRIMARY KEY,day TEXT NOT NULL,calls INTEGER NOT NULL,inputs INTEGER NOT NULL,active_ms INTEGER NOT NULL,errors INTEGER NOT NULL,received INTEGER NOT NULL,ai_calls INTEGER NOT NULL DEFAULT 0,uptime_ms INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS aggregate_day ON aggregates(day);
CREATE INDEX IF NOT EXISTS boots_day ON boots(day);
